use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl Path { # [doc = " Convert a span and an identifier to the corresponding"] # [doc = " one-segment path."] pub fn from_ident (ident : Ident) -> Path { Path { segments : thin_vec ! [PathSegment :: from_ident (ident)] , span : ident . span , tokens : None } } pub fn is_global (& self) -> bool { self . segments . first () . is_some_and (| segment | segment . ident . name == kw :: PathRoot) } # [doc = " Check if this path is potentially a trivial const arg, i.e., one that can _potentially_"] # [doc = " be represented without an anon const in the HIR."] # [doc = ""] # [doc = " If `allow_mgca_arg` is true (as should be the case in most situations when"] # [doc = " `#![feature(min_generic_const_args)]` is enabled), then this always returns true"] # [doc = " because all paths are valid."] # [doc = ""] # [doc = " Otherwise, it returns true iff the path has exactly one segment, and it has no generic args"] # [doc = " (i.e., it is _potentially_ a const parameter)."] # [tracing :: instrument (level = "debug" , ret)] pub fn is_potential_trivial_const_arg (& self , allow_mgca_arg : bool) -> bool { allow_mgca_arg || self . segments . len () == 1 && self . segments . iter () . all (| seg | seg . args . is_none ()) } }
}